let draft = $json.output ?? $json.response ?? $json.text ?? $json;
if (typeof draft === 'string') { const match = draft.match(/\{[\s\S]*\}/); if (!match) throw new Error('Draft output was not JSON.'); draft = JSON.parse(match[0]); }
const lead = $('One draft candidate per item').item.json;
const subject = String(draft.subject || '').trim();
const body = String(draft.body || '').trim();
if (!subject || subject.length > 120 || body.length < 40 || body.length > 2500) throw new Error(`Draft for opportunity ${lead.id} failed length validation.`);
return { json: { id: lead.id, subject, body, language: String(draft.language || '').trim() } };
